// Rectangular shared-memory transpose: load 64 input rows by 32 columns
// coalesced, then store the transposed 32-by-64 tile with coalesced rows.
__global__ void transposeShared64x32(float *odata, const float *idata, int n)
{
  __shared__ float tile[TILE_ROWS][TILE_DIM + 1];

  const int tileCol = blockIdx.x * TILE_DIM;
  const int tileRow = blockIdx.y * TILE_ROWS;
  const int x = tileCol + threadIdx.x;

  for (int j = 0; j < TILE_ROWS; j += BLOCK_ROWS) {
    const int row = tileRow + threadIdx.y + j;
    if (row < n && x < n)
      tile[threadIdx.y + j][threadIdx.x] =
          idata[(size_t)row * (size_t)n + (size_t)x];
  }

  __syncthreads();

  // Each thread stores eight values. Lanes vary across output columns,
  // while the shared-memory row/column indices are transposed.
  for (int i = 0; i < TILE_ROWS; i += TILE_DIM) {
    for (int j = 0; j < TILE_DIM; j += BLOCK_ROWS) {
      const int outRow = tileCol + threadIdx.y + j;
      const int outCol = tileRow + i + threadIdx.x;
      if (outRow < n && outCol < n)
        odata[(size_t)outRow * (size_t)n + (size_t)outCol] =
            tile[i + threadIdx.x][threadIdx.y + j];
    }
  }
}

extern "C" void run(const float *A, const float *B, float *C, float *scratch,
                    int n, int m, int k, float alpha, float beta)
{
  const int gridRows = n / TILE_ROWS + ((n % TILE_ROWS) != 0);
  transposeShared64x32<<<dim3(n / TILE_DIM, gridRows),
                         dim3(TILE_DIM, BLOCK_ROWS)>>>(C, A, n);
}

